style.css:
* {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
        Helvetica, Arial, sans-serif;
      line-height: 1.7;
      color: #333;
      background-color: #f9fafb;
      padding: 0;
      margin: 0;
		}

		/* 特殊文本样式 */
    font[color="#fc5531"] {
      color: #e74c3c;
      font-weight: 500;
    }
